:root{--sl:var(--ac2);--sl2:var(--ac2);--brk:linear-gradient(var(--ac2),var(--ac2)) top left/12px 1px no-repeat,linear-gradient(var(--ac2),var(--ac2)) top left/1px 12px no-repeat,linear-gradient(var(--ac2),var(--ac2)) top right/12px 1px no-repeat,linear-gradient(var(--ac2),var(--ac2)) top right/1px 12px no-repeat,linear-gradient(var(--ac2),var(--ac2)) bottom left/12px 1px no-repeat,linear-gradient(var(--ac2),var(--ac2)) bottom left/1px 12px no-repeat,linear-gradient(var(--ac2),var(--ac2)) bottom right/12px 1px no-repeat,linear-gradient(var(--ac2),var(--ac2)) bottom right/1px 12px no-repeat;--brka:linear-gradient(#ffcf6b,#ffcf6b) top left/12px 1px no-repeat,linear-gradient(#ffcf6b,#ffcf6b) top left/1px 12px no-repeat,linear-gradient(#ffcf6b,#ffcf6b) top right/12px 1px no-repeat,linear-gradient(#ffcf6b,#ffcf6b) top right/1px 12px no-repeat,linear-gradient(#ffcf6b,#ffcf6b) bottom left/12px 1px no-repeat,linear-gradient(#ffcf6b,#ffcf6b) bottom left/1px 12px no-repeat,linear-gradient(#ffcf6b,#ffcf6b) bottom right/12px 1px no-repeat,linear-gradient(#ffcf6b,#ffcf6b) bottom right/1px 12px no-repeat;--sysfont:"Bahnschrift","Segoe UI Variable Text","Segoe UI",sans-serif}
[data-chat-header]{font-family:var(--sysfont)}
nav[aria-label="Thread breadcrumb"]{text-transform:uppercase;letter-spacing:.09em;font-size:.86em}
nav[aria-label="Thread breadcrumb"] li[aria-current="page"] h2{text-shadow:0 0 10px color-mix(in srgb,var(--ac2) 50%,transparent)}
[data-panel-layout-controls] [data-slot="toggle"]{border:1px solid color-mix(in srgb,var(--ac2) 28%,transparent) !important;border-radius:2px !important;background:rgba(2,5,10,.7) !important;transition:box-shadow .15s ease,border-color .15s ease}
[data-panel-layout-controls] [data-slot="toggle"]:hover{border-color:color-mix(in srgb,var(--ac) 70%,transparent) !important;box-shadow:0 0 10px color-mix(in srgb,var(--ac2) 30%,transparent)}
[data-slot="sidebar-inner"]{box-shadow:inset -1px 0 0 color-mix(in srgb,var(--ac2) 25%,transparent);font-family:var(--sysfont);letter-spacing:.015em}
[data-testid="sidebar-project-folder"],[data-testid="sidebar-working-header"],[data-testid="sidebar-settled-header"],[data-testid="sidebar-pinned-header"]{text-transform:uppercase;letter-spacing:.1em;color:var(--ac2)}
[data-thread-item]{border-radius:2px;transition:background .15s ease;--rc:transparent}
[data-thread-item]:has([aria-label*=", Working"]),[data-thread-item]:has([aria-label*=", Connecting"]){--rc:var(--ac2)}
[data-thread-item]:has([aria-label*=", Approval"]),[data-thread-item]:has([aria-label*=", Input"]),[data-thread-item]:has([aria-label*=", Request"]),[data-thread-item]:has([aria-label*=", Waiting"]){--rc:#ffcf6b}
[data-thread-item]:has([aria-label*=", Failed"]),[data-thread-item]:has([aria-label*=", Limited"]){--rc:#ff6b85}
[data-thread-item]:has([aria-label*=", Done"]),[data-thread-item]:has([aria-label*=", Completed"]){--rc:#6fe0a0}
[data-thread-item]:hover{background:color-mix(in srgb,var(--ac2) 9%,transparent) !important}
[data-thread-item][aria-current="page"],[aria-current="page"][data-sidebar-row]{background:linear-gradient(90deg,color-mix(in srgb,var(--ac2) 20%,transparent),color-mix(in srgb,var(--ac2) 4%,transparent)) !important}
[data-slot="sidebar-footer"]{border-top:1px solid color-mix(in srgb,var(--ac2) 25%,transparent);background:rgba(2,5,10,.8)}
[data-slot="sidebar-footer"] svg{color:var(--ac2)}
[data-workspace-area="panel"]{background:linear-gradient(180deg,#03070c,#020306) !important;box-shadow:inset 1px 0 0 color-mix(in srgb,var(--ac2) 25%,transparent);font-family:var(--sysfont)}
[data-right-panel-tabbar]{border-bottom:1px solid color-mix(in srgb,var(--ac2) 30%,transparent)}
[data-right-panel-tab-list] [data-active-tab="true"]{color:var(--ac2);box-shadow:inset 0 -2px 0 var(--ac2);text-shadow:0 0 8px color-mix(in srgb,var(--ac2) 50%,transparent)}
[data-thread-details-card]{border:1px solid color-mix(in srgb,var(--ac2) 28%,transparent) !important;border-radius:3px !important;font-family:var(--sysfont);letter-spacing:.03em}
.chat-markdown h1,.chat-markdown h2,.chat-markdown h3{font-family:var(--sysfont);text-transform:uppercase;font-weight:600}
.chat-markdown h1::before,.chat-markdown h2::before{content:"[ ";color:var(--ac2)}
.chat-markdown h1::after,.chat-markdown h2::after{content:" ]";color:var(--ac2)}
.chat-markdown h3::before{content:"▸ ";color:var(--ac2)}
.chat-markdown blockquote{border-left:2px solid var(--ac2);background:color-mix(in srgb,var(--ac2) 6%,transparent);color:#b2c1d6}
.chat-markdown :not(pre)>code{border:1px solid color-mix(in srgb,var(--ac2) 25%,transparent);border-radius:3px}
.chat-markdown th{font-family:var(--sysfont);text-transform:uppercase;letter-spacing:.06em;background:color-mix(in srgb,var(--ac2) 10%,transparent)}
.chat-markdown-codeblock{border:1px solid color-mix(in srgb,var(--ac2) 30%,transparent) !important;border-radius:3px !important;background:#03060a !important}
[data-timeline-row-kind="work"],[data-timeline-row-kind="work-live"],[data-timeline-row-kind="working"]{border-left:1px solid color-mix(in srgb,var(--ac2) 40%,transparent);padding-left:8px;font-family:var(--sysfont);letter-spacing:.02em}
[data-timeline-row-kind="turn-fold"],[data-timeline-row-kind="work-toggle"]{font-family:var(--sysfont);text-transform:uppercase;letter-spacing:.1em;font-size:.82em;color:var(--ac2)}
[data-changed-files-state]{background:var(--brk),rgba(2,5,10,.9);border:1px solid color-mix(in srgb,var(--ac2) 28%,transparent);border-radius:3px;font-family:var(--sysfont)}
[data-v2-item-type="approval_request"]{background:var(--brka),rgba(30,22,6,.9) !important;border:1px solid rgba(255,207,107,.55) !important;border-radius:3px !important}
[data-testid="timeline-minimap"]{filter:hue-rotate(0deg) saturate(1.2)}
[data-slot="composer-host"]{transition:border-color .2s ease,box-shadow .2s ease}
.composer-tiptap{caret-color:var(--ac2)}
[data-placeholder]{font-family:var(--sysfont)}
[data-chat-provider-model-picker]{font-family:var(--sysfont);letter-spacing:.04em}
[data-chat-composer-footer]{font-family:var(--sysfont);text-transform:uppercase;letter-spacing:.08em;font-size:.82em}
button[type="submit"][aria-label="Submit message"]{border-radius:3px !important;box-shadow:0 0 14px color-mix(in srgb,var(--ac2) 55%,transparent)}
[data-slot="button"]{font-family:var(--sysfont);letter-spacing:.03em;transition:box-shadow .15s ease}
[data-slot="button"]:hover{box-shadow:0 0 12px color-mix(in srgb,var(--ac2) 40%,transparent)}
[data-slot="input"],[data-slot="select-trigger"]{background:#060a10 !important;border-color:color-mix(in srgb,var(--ac2) 30%,transparent) !important;border-radius:3px !important;font-family:var(--sysfont)}
[data-slot="input"]:focus,[data-slot="select-trigger"]:focus-visible{border-color:color-mix(in srgb,var(--ac) 80%,transparent) !important;box-shadow:0 0 12px color-mix(in srgb,var(--ac2) 25%,transparent)}
[data-slot="switch"][data-checked],[data-slot="switch"][aria-checked="true"]{box-shadow:0 0 10px color-mix(in srgb,var(--ac2) 55%,transparent)}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{background:var(--brk),rgba(2,5,10,.97) !important;border:1px solid color-mix(in srgb,var(--ac2) 45%,transparent) !important;border-radius:4px !important;box-shadow:0 0 30px color-mix(in srgb,var(--ac2) 18%,transparent),0 20px 60px rgba(0,0,0,.75) !important;font-family:var(--sysfont);backdrop-filter:none !important}
[data-slot="tooltip-popup"]{font-family:var(--sysfont);backdrop-filter:none !important}
[data-slot="menu-item"][data-highlighted],[data-slot="select-item"][data-highlighted],[cmdk-item][data-selected="true"]{background:linear-gradient(90deg,color-mix(in srgb,var(--ac2) 28%,transparent),color-mix(in srgb,var(--ac2) 6%,transparent)) !important;color:#fff;box-shadow:inset 2px 0 0 var(--ac2)}
[data-settings-page-scroll]{background:radial-gradient(900px 500px at 15% 0%,color-mix(in srgb,var(--ac2) 9%,transparent),transparent 60%),#020306}
[data-slot="project-monogram"]{filter:drop-shadow(0 0 4px color-mix(in srgb,var(--ac2) 65%,transparent)) saturate(1.1)}
[data-slot="project-monogram"] svg{clip-path:polygon(22% 0,100% 0,100% 78%,78% 100%,0 100%,0 22%)}
[data-timeline-row-kind="turn-fold"]::before{content:"[ QUEST COMPLETE ]";margin-right:.8em;letter-spacing:.16em;text-shadow:0 0 8px rgba(111,224,160,.45)}
[data-timeline-row-kind="working"]::before{content:"[ QUEST IN PROGRESS ]";text-shadow:0 0 8px color-mix(in srgb,var(--ac2) 50%,transparent)}
[data-thread-details-card] [role="progressbar"],[data-thread-details-card] [data-slot="progress"],[data-thread-details-card] [data-slot="meter"],[data-thread-details-card] [data-slot="slider-track"]{background:color-mix(in srgb,var(--ac2) 14%,transparent) !important;border-radius:0 !important}
[data-thread-details-card] [data-slot="progress-indicator"],[data-thread-details-card] [data-slot="meter-indicator"],[data-thread-details-card] [data-slot="slider-range"]{background:linear-gradient(90deg,var(--ac),var(--ac2)) !important;border-radius:0 !important;box-shadow:0 0 8px color-mix(in srgb,var(--ac2) 65%,transparent)}
[data-thread-details-card] [data-slot="slider-thumb"]{background:#fff !important;border-radius:1px !important;box-shadow:0 0 8px var(--ac2)}
[data-thread-details-card] input[type="range"]{accent-color:var(--ac2)}
@keyframes slSweep{from{background-position:-40% 100%,0 0}to{background-position:140% 100%,0 0}}
@keyframes slBar{0%,100%{box-shadow:inset 2px 0 0 var(--ac2),0 0 0 color-mix(in srgb,var(--ac2) 0%,transparent)}50%{box-shadow:inset 2px 0 0 var(--ac2),0 0 14px color-mix(in srgb,var(--ac2) 38%,transparent)}}
@keyframes slBreathe{0%,100%{box-shadow:0 0 0 1px color-mix(in srgb,var(--ac2) 28%,transparent),0 0 14px color-mix(in srgb,var(--ac2) 12%,transparent),0 10px 40px rgba(0,0,0,.55)}50%{box-shadow:0 0 0 1px color-mix(in srgb,var(--ac) 60%,transparent),0 0 30px color-mix(in srgb,var(--ac2) 34%,transparent),0 10px 44px rgba(0,0,0,.6)}}

@keyframes slShimmer{from{background-position:-200% 0}to{background-position:200% 0}}
@media (prefers-reduced-motion:no-preference){[data-chat-header]{animation:slSweep 5s linear infinite}
[data-thread-item]:has([aria-label*=", Working"]){animation:slBar 2.4s ease-in-out infinite}
:root:has([data-chat-canvas] :is([data-timeline-row-kind="working"],[data-timeline-row-kind="work-live"])) [data-slot="composer-host"]{animation:slBreathe 2.6s ease-in-out infinite}
[data-thread-details-card] [data-slot="progress-indicator"],[data-thread-details-card] [data-slot="slider-range"]{background-size:200% 100% !important;background-image:linear-gradient(90deg,var(--ac),var(--ac2),var(--ac)) !important;animation:slShimmer 3.5s linear infinite}}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--ac2) 28%,transparent);border-radius:2px;border:2px solid transparent;background-clip:padding-box}
::-webkit-scrollbar-thumb:hover{background:color-mix(in srgb,var(--ac) 60%,transparent);background-clip:padding-box}
[data-slot="scroll-area-thumb"]{background:color-mix(in srgb,var(--ac2) 35%,transparent) !important}
svg.lucide{stroke-width:1.6}
:root{--rank:"◆ HUNTER";--lab:"[ SYSTEM ]";--card:"[ STATUS WINDOW ]";--g:var(--ac2);--gl:color-mix(in srgb,var(--ac2) 50%,transparent)}
[data-user-message-bubble]{border:1px solid color-mix(in srgb,var(--ac2) 50%,transparent) !important;border-radius:0 !important;clip-path:polygon(0 0,100% 0,100% calc(100% - 12px),calc(100% - 12px) 100%,0 100%)}
[data-user-message-bubble]::before{content:var(--rank);display:block;margin-bottom:2px;white-space:nowrap;font:700 10px/1.4 var(--sysfont);letter-spacing:.22em;text-shadow:0 0 8px currentColor}
[data-message-role="assistant"] .chat-markdown:first-of-type::before{content:var(--lab);margin-bottom:3px}
[data-thread-details-card] span:has(> [style*="width: max("]){height:7px !important;border-radius:0 !important;-webkit-mask:repeating-linear-gradient(90deg,#000 0 5px,transparent 5px 7px);mask:repeating-linear-gradient(90deg,#000 0 5px,transparent 5px 7px)}
[data-thread-details-card] [style*="width: max("]{border-radius:0 !important;filter:drop-shadow(0 0 3px currentColor)}
[data-thread-details-card]{position:relative !important;overflow:visible !important}
[data-thread-details-card]::after{content:var(--card);position:absolute;top:-7px;left:14px;z-index:3;padding:0 7px;background:#020306;font:700 9px/1.2 var(--sysfont);letter-spacing:.26em;color:var(--g);text-shadow:0 0 8px currentColor;pointer-events:none}
:root:has([aria-label="Context window"] .bg-warning){--card:"[ MANA LOW ]";--lab:"[ ALERT ]";--g:#ffb347;--gl:rgba(255,179,71,.5)}
:root:has([aria-label="Context window"] .bg-error){--card:"[ PENALTY ZONE ]";--lab:"[ DUNGEON BREAK ]";--rank:"◆ SHADOW MONARCH";--g:#ff4d63;--gl:rgba(255,77,99,.55)}
:root:has([aria-label="Context window"] :is(.bg-warning,.bg-error)) [data-thread-details-card]{box-shadow:0 0 22px var(--gl),inset 0 0 24px rgba(0,0,0,.4) !important}
:root:has([aria-label="Context window"] :is(.bg-warning,.bg-error)) [data-slot="composer-host"]{border-color:var(--gl) !important}
:root:has([aria-label="Context window"] :is(.bg-warning,.bg-error)) [data-user-message-bubble]{border-color:var(--gl) !important}
:root:has([aria-label="Context window"] :is(.bg-warning,.bg-error)) [data-chat-header]{box-shadow:0 1px 0 var(--gl),0 8px 26px -12px var(--gl)}
[data-thread-item]{position:relative;box-shadow:none !important;background-image:linear-gradient(90deg,color-mix(in srgb,var(--rc) 14%,transparent),transparent 62%)}
[data-thread-item]::before{content:"";position:absolute;left:3px;top:24%;bottom:24%;width:3px;border-radius:3px;background:var(--rc);box-shadow:0 0 8px var(--rc);pointer-events:none}
[data-thread-item]:has([aria-label*=", Working"]),[data-thread-item]:has([aria-label*=", Connecting"]){--rc:#a4c2ea;animation:none !important}
[data-thread-item][aria-current="page"],[aria-current="page"][data-sidebar-row]{box-shadow:none !important;background-image:linear-gradient(90deg,color-mix(in srgb,var(--ac2) 26%,transparent),color-mix(in srgb,var(--ac2) 6%,transparent) 70%,transparent) !important}
[data-thread-item][aria-current="page"]::before,[aria-current="page"][data-sidebar-row]::before{top:14%;bottom:14%}
@keyframes slPill{0%,100%{opacity:1}50%{opacity:.4}}
@keyframes slFlick{0%,90%,93%,100%{opacity:1}91.5%{opacity:.35}}
@media (prefers-reduced-motion:no-preference){[data-thread-item]:has([aria-label*=", Working"])::before{animation:slPill 2.4s ease-in-out infinite}
:root:has([aria-label="Context window"] .bg-error) [data-thread-details-card]::after{animation:slFlick 2.5s infinite}}
[data-thread-details-card]{--brk:linear-gradient(90deg,var(--ac2),var(--ac)) top left / 18px 1px no-repeat,
        linear-gradient(var(--ac2),var(--ac)) top left / 1px 10px no-repeat,
        linear-gradient(90deg,var(--ac),var(--ac2)) bottom right / 18px 1px no-repeat,
        linear-gradient(var(--ac),var(--ac2)) bottom right / 1px 10px no-repeat;box-shadow:inset 0 1px 0 color-mix(in srgb,var(--ac2) 12%,transparent),0 0 14px color-mix(in srgb,var(--ac) 13%,transparent)}
:root:has([aria-label="Context window"] :is(.bg-warning,.bg-error)) [data-thread-details-card]{border-color:var(--gl) !important}
[data-chat-provider-model-picker],[data-chat-provider-model-picker] *{font-family:"Segoe UI Variable Text","Segoe UI",system-ui,sans-serif !important;letter-spacing:0 !important;text-transform:none !important}
[data-chat-provider-model-picker]{color:#dfe9ff !important;font-size:12.5px;font-weight:600;padding:3px 10px;transition:border-color .15s ease,box-shadow .15s ease}
@keyframes slNeb{0%,100%{filter:hue-rotate(0deg) brightness(1)}50%{filter:hue-rotate(-18deg) brightness(1.15)}}
@media (prefers-reduced-motion:no-preference){button[aria-label="Submit message"]{animation:slNeb 6s ease-in-out infinite}}
:root{--g:var(--ac);--gl:color-mix(in srgb,var(--ac) 45%,transparent)}
.chat-markdown a{color:var(--ac) !important;text-decoration-color:color-mix(in srgb,var(--ac2) 45%,transparent)}
.chat-markdown :not(pre)>code{background:color-mix(in srgb,var(--ac) 12%,transparent) !important;border-color:color-mix(in srgb,var(--ac) 32%,transparent) !important;color:var(--ac2) !important}
.chat-markdown-codeblock{border-color:color-mix(in srgb,var(--ac) 34%,transparent) !important}
[data-thread-item][aria-current="page"]::before,[aria-current="page"][data-sidebar-row]::before{background:linear-gradient(var(--ac2),var(--ac)) !important;box-shadow:0 0 10px color-mix(in srgb,var(--ac) 90%,transparent) !important}
[data-thread-item]:has([aria-label*=", Working"]),[data-thread-item]:has([aria-label*=", Connecting"]){--rc:var(--ac)}
[data-thread-details-card] [style*="width: max("]:not(.bg-error):not(.bg-warning){background:var(--ac) !important}
[data-message-role="assistant"] .chat-markdown:first-of-type::before{display:inline-block !important;margin:0 0 6px !important;font:700 10px/1.5 var(--sysfont) !important;letter-spacing:.24em !important;border-left:2px solid var(--ac);text-shadow:0 0 8px color-mix(in srgb,var(--ac2) 80%,transparent) !important}
.chat-markdown h1,.chat-markdown h2,.chat-markdown h3{color:#eaf3ff !important;text-shadow:0 0 12px color-mix(in srgb,var(--ac) 65%,transparent) !important;letter-spacing:.07em !important;font-size:1.02em !important}
.chat-markdown h1,.chat-markdown h2{border-bottom:0 !important;padding-bottom:.35em}
.chat-markdown h1::before,.chat-markdown h2::before,.chat-markdown h3::before{content:"◆ " !important;font-size:.8em}
.chat-markdown h1::after,.chat-markdown h2::after,.chat-markdown h3::after{content:none !important}
[data-timeline-row-kind="turn-fold"]::before{color:#5fe3a2 !important}
button[aria-label="Submit message"]:hover{box-shadow:0 0 22px color-mix(in srgb,var(--ac2) 85%,transparent),inset 0 0 12px color-mix(in srgb,var(--ac2) 40%,transparent) !important}
[data-slot="composer-host"]{border:1px solid #16345e !important;border-radius:3px !important;box-shadow:none !important;animation:none !important}
button[aria-label="Submit message"]{animation:none !important}
button[aria-label="Submit message"]:not(:disabled):not([aria-disabled="true"]):hover{background:var(--ac) !important}
[data-chat-provider-model-picker]{background:#080f1b !important;border:1px solid #23416b !important;border-radius:3px !important;box-shadow:none !important}
:is([data-chat-provider-model-picker],button[aria-label="Submit message"]):focus-visible{outline:2px solid var(--ac);outline-offset:2px}
[data-message-role="assistant"] .chat-markdown:first-of-type::before{background:none !important;border:0 !important;padding:0 !important;text-shadow:0 0 8px var(--acg)}
:is([data-slot="composer-host"],[data-thread-details-card]) [data-slot="button"]:not([aria-label="Submit message"],[data-chat-provider-model-picker]){color:#91a8c6;border-radius:3px;box-shadow:none}
[data-thread-item][aria-current="page"]{background-image:none !important}
[data-thread-item][aria-current="page"]::before{box-shadow:none !important}
[data-panel-layout-controls] [data-slot="toggle"][data-pressed]{box-shadow:none !important}

@keyframes nsScan{from{background-position:-60% 0,0 0}to{background-position:160% 0,0 0}}
@keyframes nsBreathe{0%,100%{box-shadow:0 0 0 1px color-mix(in srgb,var(--ac) 25%,transparent),0 0 10px color-mix(in srgb,var(--ac) 10%,transparent)}50%{box-shadow:0 0 0 1px color-mix(in srgb,var(--ac2) 70%,transparent),0 0 24px color-mix(in srgb,var(--ac) 35%,transparent)}}
@keyframes nsStop{0%,100%{box-shadow:0 0 0 0 rgba(255,77,99,.55)}60%{box-shadow:0 0 0 7px rgba(255,77,99,0)}}
@keyframes nsSheen{from{transform:translateX(-120%)}to{transform:translateX(220%)}}
@keyframes nsTitle{0%,100%{text-shadow:0 0 6px color-mix(in srgb,var(--ac2) 35%,transparent)}50%{text-shadow:0 0 14px color-mix(in srgb,var(--ac2) 90%,transparent)}}
[data-workspace-area="conversation"]{position:relative !important;isolation:isolate;overflow:clip}
.messages-timeline-scroll{position:relative;z-index:1}
[data-slot="composer-host"]{position:relative}
[data-slot="composer-host"]::before{content:"COMMAND" !important;position:absolute;top:-7px;left:14px;z-index:3;padding:0 7px;background:#020306;font:700 9px/1.2 var(--sysfont);letter-spacing:.3em;pointer-events:none}
[data-slot="composer-host"]::after{content:"" !important;position:absolute;left:0;right:0;top:-1px;height:1px;pointer-events:none;background:linear-gradient(90deg,transparent,var(--ac2),transparent) -60% 0/40% 1px no-repeat;opacity:0}
.composer-tiptap{font-size:14.5px;line-height:1.55}
[data-placeholder]{color:#4f6c96 !important;font-style:normal;letter-spacing:.05em}
@media (prefers-reduced-motion:no-preference){[data-slot="composer-host"]:focus-within::after{opacity:1;animation:nsScan 3.2s linear infinite}
:root:has([data-chat-canvas] :is([data-timeline-row-kind="working"],[data-timeline-row-kind="work-live"])) [data-slot="composer-host"]{animation:nsBreathe 2.4s ease-in-out infinite !important}}
button[aria-label="Submit message"]{position:relative}
button[aria-label="Submit message"]::after{content:"";position:absolute;inset:0;background:linear-gradient(100deg,transparent 30%,rgba(255,255,255,.35) 50%,transparent 70%);transform:translateX(-120%);pointer-events:none}
button[aria-label="Submit message"]:not(:disabled):hover::after{animation:nsSheen .7s ease}
button[aria-label="Stop generation"],button[aria-label="Stopping"]{box-shadow:none}
@media (prefers-reduced-motion:no-preference){button[aria-label="Stop generation"]{animation:nsStop 1.6s ease-out infinite}}
[data-chat-header]{box-shadow:none !important}
